const e=[{id:1,label:"Criterio",question:"¿Qué es un criterio de evaluación?",options:["La nota vigesimal que se registra en el acta oficial.","El referente específico y observable que describe qué se espera valorar del desempeño.","La cantidad de hojas o páginas que debe tener la tarea.","El tiempo límite otorgado para resolver un examen escrito."],correctIndex:1,concept:"Criterio de evaluación",explanation:"Un criterio es el referente específico que orienta qué cualidades del desempeño del estudiante se van a observar y valorar en relación con la competencia.",example:'Ejemplo: "Explica las causas y consecuencias del calentamiento global utilizando fuentes confiables".'},{id:2,label:"Descriptor",question:"¿Qué función cumple un descriptor dentro de una rúbrica?",options:["Define de manera observable lo que el estudiante es capaz de hacer en cada nivel de logro.","Asigna automáticamente un puntaje numérico sin necesidad de leer la evidencia.","Indica la bibliografía obligatoria que el docente utilizó para planificar.","Resume el índice general de la unidad pedagógica."],correctIndex:0,concept:"Descriptor de nivel",explanation:"El descriptor concreta en términos cualitativos, observables y progresivos el desempeño que caracteriza a cada nivel de logro para un criterio determinado.",example:'Ejemplo: En nivel A: "Identifica al menos 3 causas y 3 consecuencias con respaldo empírico".'},{id:3,label:"Niveles",question:"¿Cuáles son los cuatro niveles de logro según el enfoque formativo?",options:["Excelente, Bueno, Regular y Deficiente.","En inicio (C), En proceso (B), Logro esperado (A) y Logro destacado (AD).","Alto, Medio-Alto, Medio-Bajo e Insuficiente.","Aprobado, Desaprobado, Aplazado y Exonerado."],correctIndex:1,concept:"Niveles de logro",explanation:"El Currículo Nacional establece una escala cualitativa de progresión: En inicio (C), En proceso (B), Logro esperado (A) y Logro destacado (AD).",example:"Ejemplo: C indica dificultades que requieren acompañamiento cercano; AD demuestra dominio que supera lo esperado para el grado."},{id:4,label:"AD vs A",question:"¿Qué diferencia cualitativa fundamental existe entre los niveles AD y A?",options:["El nivel AD exige hacer el doble de ejercicios en el mismo tiempo.","AD evidencia un desempeño más allá del nivel esperado para el grado, mientras que A alcanza el nivel previsto.","AD es exclusivamente para estudiantes de secundaria y A para primaria.","No existe diferencia conceptual, solo es una distinción numérica administrativa."],correctIndex:1,concept:"Diferenciación de logros",explanation:"El nivel A certifica que el estudiante ha alcanzado satisfactoriamente el nivel previsto para el periodo; el nivel AD evidencia un desempeño que va más allá de lo esperado, mostrando transferencia y autonomía excepcional.",example:"Ejemplo: En A aplica un procedimiento en contextos conocidos; en AD transfiere el principio a un contexto inédito y propone soluciones innovadoras."},{id:5,label:"Transparencia",question:"¿Por qué es indispensable compartir los criterios de evaluación con los estudiantes antes de la actividad?",options:["Para evitar que los estudiantes hagan preguntas durante la sesión.","Para que puedan autorregular su aprendizaje, autoevaluarse y saber qué se espera de su desempeño.","Es un requisito puramente formal sin impacto en el aprendizaje.","Para que los padres de familia califiquen las tareas en casa."],correctIndex:1,concept:"Autorregulación y transparencia",explanation:"Compartir y clarificar los criterios empodera al estudiante: le permite comprender la meta, monitorear su propio proceso y coevaluar con objetividad a sus compañeros.",example:"Ejemplo: Analizar una rúbrica en conjunto antes de redactar un ensayo para saber qué elementos debe incluir."},{id:6,label:"Evidencia",question:"¿Qué relación pedagógica existe entre una evidencia y un criterio de evaluación?",options:["Son términos idénticos e intercambiables en cualquier contexto.","La evidencia es la producción o actuación concreta, y el criterio es el referente con el que se juzga su calidad.","La evidencia se construye después de haber puesto la calificación con el criterio.","El criterio solo se utiliza cuando la evidencia no tiene nota numérica."],correctIndex:1,concept:"Relación Evidencia-Criterio",explanation:"La evidencia es el producto tangible o actuación observable realizada por el estudiante; el criterio es la guía de calidad que permite interpretar cuán desarrollada está la competencia en esa evidencia.",example:'Ejemplo: Evidencia = "Podcast sobre la biodiversidad local". Criterio = "Claridad argumentativa y respaldo en fuentes científicas".'}],a=[{id:1,question:"¿Qué tipo de rúbrica permite valorar cada criterio por separado?",options:["Holística","Analítica","Lista de cotejo","Registro anecdótico"],correctIndex:1,explanation:"La rúbrica analítica desagrega la competencia en criterios específicos independientes, permitiendo evaluar fortalezas y necesidades particulares en cada dimensión."},{id:2,question:"¿Cuál es la principal ventaja de una rúbrica analítica para la retroalimentación formativa?",options:["Permite calificar en menos de un minuto sin leer el trabajo completo.","Ofrece información detallada y precisa sobre qué aspectos específicos debe mejorar el estudiante.","Elimina por completo la necesidad de que el docente dialogue con el alumno.","Garantiza que todos los estudiantes obtengan la calificación máxima."],correctIndex:1,explanation:"Al desglosar el desempeño por criterios, el estudiante y el docente saben exactamente en qué criterio se alcanzó el logro y en cuál se requiere mayor apoyo."},{id:3,question:"¿En qué se diferencia una lista de cotejo de una rúbrica?",options:["La lista de cotejo es dicotómica (presencia o ausencia), mientras que la rúbrica describe niveles progresivos de calidad.","La lista de cotejo solo se usa en universidades y la rúbrica en inicial.","La lista de cotejo nunca lleva criterios de evaluación.","No hay diferencias; ambos instrumentos son cualitativamente idénticos."],correctIndex:0,explanation:"La lista de cotejo verifica si un elemento está presente o ausente (Sí/No). La rúbrica va mucho más allá: describe los distintos grados de calidad del desempeño mediante descriptores."},{id:4,question:"Al redactar descriptores en una rúbrica, ¿qué práctica debe evitarse rigurosamente?",options:["Usar verbos que describan acciones observables.",'Utilizar adjetivos ambiguos o vagos como "excelente", "bueno" o "bonito" sin concretar el desempeño.',"Diferenciar claramente el nivel A del nivel B.","Vincular el descriptor con el estándar de aprendizaje del ciclo."],correctIndex:1,explanation:"Los adjetivos vagos son subjetivos e impiden al estudiante saber qué debe demostrar. Los descriptores deben formularse con evidencias observables y comprensibles."},{id:5,question:"¿Qué instrumento es más idóneo para registrar hechos imprevistos y significativos durante una sesión de aprendizaje?",options:["Rúbrica holística","Escala de valoración","Registro anecdótico","Examen de opción múltiple"],correctIndex:2,explanation:"El registro anecdótico es una descripción breve, objetiva e inmediata de un comportamiento o acontecimiento imprevisto pero pedagógicamente significativo del estudiante."}],i=[{id:1,title:"Caso 1: El misterio de los adjetivos vacíos",suspectInstrument:"Rúbrica de expresión oral",defectSnippet:`Criterio: Dicción y claridad
• Nivel AD: Dicción excelente y muy bonita.
• Nivel A: Dicción buena.
• Nivel B: Dicción regular.
• Nivel C: Dicción mala.`,caseDescription:"La docente utilizó adjetivos genéricos como «excelente», «bueno», «regular» y «malo», sin explicar qué debe demostrar el estudiante en cada nivel.",challenge:"¿Cuál es el problema fundamental y cómo debe resolverse?",options:[{text:'El problema es que faltó agregar el nivel "Muy Malo"; se resuelve añadiendo más categorías negativas.',isCorrect:!1,feedback:"Incorrecto. Agregar más adjetivos negativos no aclara qué se espera observar en el estudiante."},{text:"Los adjetivos son vagos y subjetivos. Debe sustituirse por descriptores observables de entonación, volumen audible y modulación adecuada.",isCorrect:!0,feedback:"¡Excelente deducción, detective! Los descriptores deben explicitar conductas observables (ej. pronuncia con claridad, modula el volumen según el auditorio)."},{text:"El único error es que debió redactarse en números del 1 al 20 en lugar de letras.",isCorrect:!1,feedback:"Incorrecto. El problema radica en la ausencia de descriptores cualitativos observables, no en el formato de calificación."}],resolutionGuide:'Para corregir este error, formula qué hace el estudiante: "Pronuncia las palabras con precisión y modula el volumen de voz para que todos los oyentes lo escuchen con facilidad".'},{id:2,title:"Caso 2: La trampa de la cantidad vs calidad",suspectInstrument:"Rúbrica de ensayo argumentativo",defectSnippet:`Criterio: Pensamiento crítico y sustentación
• Nivel AD: Escribe más de 5 páginas.
• Nivel A: Escribe 3 a 4 páginas.
• Nivel B: Escribe 2 páginas.
• Nivel C: Escribe menos de 1 página.`,caseDescription:"El docente intentó graduar el pensamiento crítico únicamente contando el número de páginas escritas.",challenge:"¿Por qué este criterio está viciado y cómo debe corregirse?",options:[{text:"Porque la extensión física no garantiza profundidad reflexiva ni solidez en los argumentos. Debe evaluarse la coherencia y el respaldo de las premisas.",isCorrect:!0,feedback:"¡Exacto! Un ensayo de una página puede tener un análisis brillante y uno de cinco páginas ser redundante o inconexo."},{text:"Porque para el nivel AD debió exigir un mínimo de 10 páginas para que investiguen más.",isCorrect:!1,feedback:"Incorrecto. Exigir más volumen no mejora la calidad del pensamiento crítico."},{text:"Porque en lugar de páginas debió contar el número de palabras en el procesador de texto.",isCorrect:!1,feedback:"Incorrecto. La medición cuantitativa sigue sin medir la calidad argumentativa."}],resolutionGuide:"La calidad argumentativa se describe mediante: solidez de las razones, pertinencia de las fuentes, refutación de contraargumentos y coherencia en las conclusiones."},{id:3,title:"Caso 3: El salto invisible de dificultad",suspectInstrument:"Rúbrica de indagación científica",defectSnippet:`Criterio: Formulación de hipótesis
• Nivel A: Plantea una hipótesis basada en conocimientos científicos.
• Nivel AD: Plantea una hipótesis, diseña el experimento completo, elabora un video documental y programa un software.`,caseDescription:"Para el nivel destacado (AD), la rúbrica exige repentinamente habilidades ajenas al criterio de formulación de hipótesis (edición de video y programación).",challenge:"¿Qué incoherencia se detecta y cómo garantizar la coherencia interna?",options:[{text:"El nivel AD siempre debe incluir tecnología audiovisual obligatoria, así no tenga relación con el criterio.",isCorrect:!1,feedback:"Incorrecto. La tecnología sin propósito formativo desvirtúa el criterio a evaluar."},{text:"Se perdió la coherencia del criterio: se evalúa producción audiovisual en lugar de la calidad de la hipótesis. El nivel AD debe profundizar en la delimitación de variables.",isCorrect:!0,feedback:"¡Brillante detective! El nivel AD del mismo criterio debe referirse a establecer relaciones complejas entre variables independientes, dependientes e intervinientes."},{text:"No hay ningún problema, mientras más cosas complejas se pidan en AD, mejor.",isCorrect:!1,feedback:"Incorrecto. Introducir criterios ajenos invalida la rúbrica y confunde la evaluación formativa."}],resolutionGuide:"Conserva el foco del criterio: en AD el estudiante puede prever variables intervinientes complejas o justificar el sustento probabilístico de su hipótesis."}],o=[{id:1,term:"Evidencia",definition:"Producción, producto o actuación que demuestra lo que el estudiante sabe hacer con lo aprendido."},{id:2,term:"Criterio",definition:"Parámetro o referente específico que describe las cualidades del desempeño esperado frente a la competencia."},{id:3,term:"Descriptor",definition:"Enunciado observable que concreta el desempeño en cada uno de los niveles de logro de una rúbrica."},{id:4,term:"Rúbrica Analítica",definition:"Instrumento que evalúa y desglosa cada criterio por separado, facilitando la retroalimentación precisa."},{id:5,term:"Rúbrica Holística",definition:"Instrumento que valora de manera global e integrada el desempeño del estudiante en un solo bloque."},{id:6,term:"Retroalimentación",definition:"Diálogo formativo que orienta al estudiante sobre sus logros, dificultades y cómo avanzar hacia la meta."},{id:7,term:"Niveles de Logro",definition:"Escala cualitativa (C, B, A, AD) que expresa la progresión del desarrollo de una competencia."},{id:8,term:"Lista de Cotejo",definition:"Instrumento dicotómico que verifica si un rasgo o acción está presente o ausente en el trabajo."},{id:9,term:"Autoevaluación",definition:"Proceso reflexivo donde el propio estudiante valora su desempeño a la luz de los criterios compartidos."},{id:10,term:"Coevaluación",definition:"Valoración recíproca entre pares o compañeros sobre sus producciones usando criterios comunes."},{id:11,term:"Escala de Valoración",definition:"Instrumento graduado que permite valorar la frecuencia o grado de intensidad de una conducta observada."},{id:12,term:"Estándar",definition:"Descripción holística y común de lo que se espera alcance el estudiante al finalizar un ciclo educativo."}],n=[{id:1,question:"¿Qué tipo de rúbrica evalúa cada criterio por separado?",options:["Analítica","Holística"],correctAnswer:"Analítica",quickFeedback:"La rúbrica analítica desglosa la competencia en criterios independientes."},{id:2,question:"¿Cuál permite valorar un desempeño de manera global e integrada?",options:["Analítica","Holística"],correctAnswer:"Holística",quickFeedback:"La rúbrica holística juzga el producto en su totalidad sin separar criterios."},{id:3,question:"¿Qué instrumento facilita identificar con exactitud dificultades específicas en cada dimensión?",options:["Analítica","Holística"],correctAnswer:"Analítica",quickFeedback:"Al tener descriptores por criterio, señala con precisión qué aspecto requiere mejora."},{id:4,question:"¿Cuál sería más ágil y adecuada para valorar integralmente una exposición final como jurado general?",options:["Analítica","Holística"],correctAnswer:"Holística",quickFeedback:"La holística es óptima cuando se busca una valoración global rápida del desempeño general."},{id:5,question:"Ofrece retroalimentación detallada y personalizada para orientar la mejora continua.",options:["Analítica","Holística"],correctAnswer:"Analítica",quickFeedback:"El desglose analítico es el más potente para la retroalimentación formativa formativa."},{id:6,question:"Describe cada nivel de logro combinando todos los aspectos del trabajo en un único párrafo descriptivo.",options:["Analítica","Holística"],correctAnswer:"Holística",quickFeedback:"En la holística, cada nivel (AD, A, B, C) es un párrafo integrador que abarca todo el trabajo."},{id:7,question:"El estudiante puede tener Logro Destacado en redacción pero En Proceso en sustento empírico.",options:["Analítica","Holística"],correctAnswer:"Analítica",quickFeedback:"La analítica permite obtener diferentes niveles de logro en criterios distintos."},{id:8,question:"Se asigna un único nivel global al estudiante sin puntajes intermedios por criterio.",options:["Analítica","Holística"],correctAnswer:"Holística",quickFeedback:"La holística asigna una única valoración sintética para todo el desempeño."}],r=[{level:1,prizeText:"Nivel 1: Conceptos Básicos",question:"¿Cuál es el fin primordial de la evaluación formativa de los aprendizajes?",options:["Clasificar y reprobar a los estudiantes con bajo rendimiento.","Identificar fortalezas y necesidades para mejorar continuamente los procesos de aprendizaje y enseñanza.","Calcular el promedio numérico bimestral con exactitud matemática.","Controlar la disciplina y asistencia en el aula escolar."],correctIndex:1,explanation:"La evaluación formativa se centra en el aprendizaje del estudiante: busca recopilar evidencia para retroalimentar y ajustar oportunamente la enseñanza.",audienceStats:[4,88,5,3],fiftyFiftyRemove:[0,3],hint:"Piensa en el propósito orientador: mejorar el aprendizaje y ayudar a superar dificultades."},{level:2,prizeText:"Nivel 2: Agentes de Evaluación",question:"Cuando los estudiantes evalúan cooperativamente los trabajos de sus compañeros basándose en criterios compartidos, se realiza una:",options:["Heteroevaluación unilineal","Coevaluación formativa","Metaevaluación sumativa","Evaluación diagnóstica externa"],correctIndex:1,explanation:"La coevaluación es la valoración recíproca entre pares; fomenta el juicio crítico, el respeto y la comprensión profunda de los criterios de calidad.",audienceStats:[6,85,5,4],fiftyFiftyRemove:[0,2],hint:'El prefijo "Co-" hace referencia a la colaboración mutua entre pares iguales.'},{level:3,prizeText:"Nivel 3: Alineación Pedagógica",question:"Para que los criterios de evaluación sean válidos y pertinentes, deben formularse a partir de:",options:["Las preferencias arbitrarias de los padres de familia.","Los estándares de aprendizaje y las capacidades de la competencia a evaluar.","La cantidad de ejercicios del libro que faltan por resolver.","El reglamento interno disciplinario de la institución."],correctIndex:1,explanation:"Los criterios de evaluación se derivan directamente de los estándares y capacidades de la competencia, garantizando coherencia con el currículo oficial.",audienceStats:[3,91,4,2],fiftyFiftyRemove:[2,3],hint:"La referencia obligatoria del Currículo Nacional son los estándares y las capacidades."},{level:4,prizeText:"Nivel 4: Graduación de Descriptores",question:'En una rúbrica, ¿qué distingue al nivel "En inicio" (C) del nivel "En proceso" (B)?',options:["En inicio el estudiante no asiste a clases y en proceso sí asiste.","En inicio muestra dificultades recurrentes que exigen acompañamiento permanente; en proceso evidencia avances pero aún requiere mediación.","En inicio tiene 00 y en proceso tiene 11.","No hay distinción pedagógica relevante."],correctIndex:1,explanation:"El nivel C denota avances muy incipientes con necesidad de apoyo constante; el nivel B muestra logros parciales orientados hacia el nivel esperado.",audienceStats:[2,92,4,2],fiftyFiftyRemove:[0,3],hint:"Fíjate en el grado de autonomía y la necesidad de acompañamiento del docente."},{level:5,prizeText:"Nivel 5: Nivel Experto (Pregunta Final de Camila)",question:"Una docente desea evaluar una propuesta para prevenir la discriminación en su escuela. ¿Qué elementos esenciales debe considerar al construir su rúbrica?",options:["Únicamente el diseño gráfico, el tipo de letra y la extensión de hojas del documento.","El propósito de aprendizaje, la evidencia concreta, los criterios alineados, los descriptores observables y los niveles de logro graduados.","La cantidad de sanciones que la propuesta aplicará a los infractores.","El visto bueno de la dirección antes de definir los criterios."],correctIndex:1,explanation:"¡Respuesta maestra! Toda rúbrica formativa debe articular coherentemente: propósito pedagógico, evidencia auténtica, criterios de calidad, descriptores observables y los 4 niveles de logro.",audienceStats:[1,96,2,1],fiftyFiftyRemove:[0,2],hint:"Recuerda los 5 pilares estructurales: propósito, evidencia, criterios, descriptores y niveles de logro."}],s={situation:"Situación: Elaborar una propuesta comunitaria para prevenir el acoso escolar en la institución educativa.",taskCondition:"Condición del reto: Construir la rúbrica analítica asignando a cada nivel (C, B, A, AD) el descriptor que le corresponde con coherencia pedagógica.",criteria:[{id:1,name:"Criterio 1: Diagnóstico de la problemática",description:"Identifica las manifestaciones, causas y consecuencias del acoso escolar.",shuffledDescriptors:[{id:"1-A",level:"A",text:"Identifica las causas directas y las consecuencias del acoso escolar sustentándose en testimonios o datos de su entorno escolar."},{id:"1-C",level:"C",text:"Menciona situaciones aisladas de conflicto sin identificar causas claras ni consecuencias del acoso escolar, requiriendo apoyo constante."},{id:"1-AD",level:"AD",text:"Analiza críticamente factores socioemocionales e institucionales del acoso escolar, diferenciando tipologías y proponiendo indicadores de alerta temprana."},{id:"1-B",level:"B",text:"Describe manifestaciones visibles de acoso escolar e identifica algunas causas básicas, pero sus consecuencias aún son superficiales."}]},{id:2,name:"Criterio 2: Acciones preventivas propuestas",description:"Diseña estrategias pertinentes, inclusivas y viables para erradicar el acoso.",shuffledDescriptors:[{id:"2-B",level:"B",text:"Plantea actividades de sensibilización generales, pero sin detallar responsables ni momentos específicos para su ejecución."},{id:"2-AD",level:"AD",text:"Diseña un plan integral con protocolos de respuesta, actividades de convivencia positiva y mecanismos de seguimiento liderados por los propios estudiantes."},{id:"2-A",level:"A",text:"Propone acciones preventivas viables y participativas con objetivos claros, dirigidas a estudiantes y docentes de la comunidad escolar."},{id:"2-C",level:"C",text:"Sugiere medidas punitivas o castigos sin contemplar la prevención formativa ni la participación de la comunidad educativa."}]},{id:3,name:"Criterio 3: Viabilidad y compromiso comunitario",description:"Involucra a los actores escolares y asegura recursos realistas.",shuffledDescriptors:[{id:"3-AD",level:"AD",text:"Establece alianzas estratégicas con tutores, familias y especialistas, previendo recursos sostenibles y un cronograma de monitoreo continuo."},{id:"3-C",level:"C",text:"No contempla recursos ni la participación de otros miembros de la comunidad, esperando que otros resuelvan la propuesta."},{id:"3-B",level:"B",text:"Señala recursos elementales pero su distribución de tareas es poco clara entre los miembros del equipo escolar."},{id:"3-A",level:"A",text:"Define roles específicos para estudiantes y tutores, empleando recursos disponibles en el aula y la escuela de manera responsable."}]}]},t=[{id:1,category:"Criterios y Descriptores",question:"¿Comprendes la función pedagógica de un criterio y cómo redactar sus descriptores?",greenText:"Comprendo con claridad cómo redactar descriptores observables y progresivos.",yellowText:"Tengo noción general, pero a veces dudo en cómo formular la progresión entre niveles.",redText:"Aún me cuesta distinguir entre un descriptor cualitativo y un adjetivo calificativo vago.",recommendations:{green:"¡Excelente dominio! Continúa ejercitando la redacción contextualizada con tus pares.",yellow:'Revisa la regla de oro: usa verbos de acción observable y evita adjetivos como "bueno" o "regular".',red:"Te recomendamos repasar los casos de Detectives Digitales y las páginas 12 a 16 del libro."}},{id:2,category:"Rúbrica Analítica vs Holística",question:"¿Diferencias cuándo es más conveniente utilizar una rúbrica analítica y cuándo una holística?",greenText:"Distingo claramente las ventajas de cada instrumento según el propósito evaluativo.",yellowText:"Identifico la analítica, pero la formulación de la rúbrica holística me genera confusión.",redText:"Me resulta difícil decidir qué instrumento utilizar según la evidencia solicitada.",recommendations:{green:"¡Muy bien! Recuerda que la analítica es óptima para retroalimentar y la holística para valorar el todo integrado.",yellow:'Practica la actividad "Carrera contra el tiempo" para afianzar las situaciones prácticas de aula.',red:"Revisa el cuadro comparativo del libro sobre instrumentos de evaluación formativa."}},{id:3,category:"Niveles de Logro (C, B, A, AD)",question:'¿Identificas cómo graduar el desempeño desde "En inicio" (C) hasta "Logro destacado" (AD)?',greenText:"Puedo diferenciar el nivel previsto (A) de la autonomía superior del nivel destacado (AD).",yellowText:"Entiendo C, B y A, pero me resulta complejo formular el valor agregado del nivel AD.",redText:"Tiendo a medir la progresión solo por cantidad de errores o número de páginas.",recommendations:{green:"¡Excelente sentido pedagógico! El nivel AD siempre demuestra transferencia y creatividad.",yellow:"En AD, piensa en qué hace el estudiante cuando transfiere lo aprendido a un contexto novedoso.",red:"Recuerda: la evaluación por competencias valora calidad y complejidad del pensamiento, no cantidad física."}},{id:4,category:"Pregunta Final de Camila",question:"¿Te sientes preparado/a para construir una rúbrica de evaluación completa para tus estudiantes?",greenText:"¡Totalmente preparado! Sé articular propósito, evidencia, criterios y descriptores.",yellowText:"Me siento con buena base, pero desearía validar mi rúbrica con un colega antes de aplicarla.",redText:"Todavía requiero más ejemplos prácticos antes de diseñar una rúbrica propia.",recommendations:{green:"¡Felicitaciones! Has completado con éxito la ruta de aprendizaje de Camila.",yellow:"La coevaluación docente es una gran práctica formativa: contrasta tus descriptores con tus colegas.",red:"Vuelve a interactuar con la Batalla de Equipos y La Ruleta del Saber para consolidar cada fase."}}];export{e as C,a,i as b,o as c,n as d,r as e,s as f,t as g};
